//! Round-6 bug hunt: PDF extraction (pdf / pdf_oxide features), segments, page_type.
//! Fixtures in tests/bughunt6_data were generated by gen.py / gen2.py / gen3.py
//! (reportlab, pypdf, fpdf2+uharfbuzz, matplotlib), so the ground-truth text is known.
//! Reference extractors on the same files: PyMuPDF 1.26 and poppler pdftotext.
//! Run: cargo test --features pdf,pdf_oxide --test bughunt6
#![allow(dead_code)]

#[cfg(feature = "pdf")]
fn fixture(name: &str) -> Vec<u8> {
    std::fs::read(format!(
        "{}/tests/bughunt6_data/{name}",
        env!("CARGO_MANIFEST_DIR")
    ))
    .unwrap()
}

#[cfg(all(feature = "pdf", feature = "pdf_oxide"))]
#[test]
#[ignore = "probe: prints every fixture through every PDF entry point"]
fn probe_pdf_dump() {
    let dir = format!("{}/tests/bughunt6_data", env!("CARGO_MANIFEST_DIR"));
    let mut names: Vec<_> = std::fs::read_dir(&dir)
        .unwrap()
        .filter_map(|e| {
            let n = e.unwrap().file_name().into_string().unwrap();
            n.ends_with(".pdf").then_some(n)
        })
        .collect();
    names.sort();
    for n in names {
        let b = fixture(&n);
        match deformat::pdf::extract_bytes(&b) {
            Ok(e) => println!("{n}: TEXT {:?}", e.text),
            Err(e) => println!("{n}: ERR {e}"),
        }
        match deformat::pdf_oxide::extract_bytes_to_segments_with_coords(&b) {
            Ok(segs) => {
                for s in segs {
                    let d = s.data();
                    let c = d.metadata.coordinates.as_ref().unwrap();
                    println!(
                        "   p{:?} {:?} pts={:?} lw={} lh={}",
                        d.metadata.page_number, d.text, c.points, c.layout_width, c.layout_height
                    );
                }
            }
            Err(e) => println!("   coords ERR {e}"),
        }
    }
}

// ---------------------------------------------------------------- text decoding

/// reportlab embeds TrueType subsets as simple fonts named AAAAAA+DejaVuSans
/// whose non-ASCII glyphs get codes 1..31; each file's /ToUnicode CMap maps
/// <01> to its own character (ttf_lig: U+FB01, ttf_plain: U+00E9, ttf_latin1:
/// U+00E0). pdf_oxide 0.3.38 keeps a process-global font cache keyed by
/// BaseFont + Subtype + ToUnicode *object number* (document.rs:8866-8913,
/// 9081-9093), so the second and later files reuse the first file's font.
/// Each file alone decodes correctly (PyMuPDF / pdftotext agree); in sequence
/// at least two of the three must come out wrong, whatever ran first.
#[cfg(feature = "pdf")]
#[test]
fn pdf_text_does_not_depend_on_previously_extracted_documents() {
    let cases = [
        (
            "ttf_lig.pdf",
            "\u{fb01}nd the \u{fb02}ow and o\u{fb00}er",
            "find the flow and offer",
        ),
        ("ttf_plain.pdf", "Café naïve über", "Café naïve über"),
        (
            "ttf_latin1.pdf",
            "àáâãäåæçèéêëìíîïðñòóôõöøùúûüýþÿ",
            "àáâãäåæçèéêëìíîïðñòóôõöøùúûüýþÿ",
        ),
    ];
    let mut bad = Vec::new();
    for (name, raw, expanded) in cases {
        let got = deformat::pdf::extract_bytes(&fixture(name)).unwrap().text;
        if !(got.contains(raw) || got.contains(expanded)) {
            bad.push(format!("{name}: {got:?}"));
        }
    }
    assert!(
        bad.is_empty(),
        "wrong text after earlier extractions: {bad:#?}"
    );
}

/// Each file alone (run this test by itself: `-- --exact pdf_single_document_tounicode_isolated`)
/// decodes correctly; in a shared test process it is order dependent.
#[cfg(feature = "pdf")]
#[test]
#[ignore = "order dependent by design of the bug above; run alone"]
fn pdf_single_document_tounicode_isolated() {
    let got = deformat::pdf::extract_bytes(&fixture("ttf_plain.pdf"))
        .unwrap()
        .text;
    assert!(got.contains("Café naïve über"), "got {got:?}");
}

/// Control: the same characters through standard Helvetica/WinAnsi decode fine.
#[cfg(feature = "pdf")]
#[test]
fn pdf_winansi_control() {
    let got = deformat::pdf::extract_bytes(&fixture("helv_latin1.pdf"))
        .unwrap()
        .text;
    assert!(
        got.contains("Grüße aus München, £ 5 € 7 café"),
        "got {got:?}"
    );
}

/// Shaped ligatures (fpdf2 + HarfBuzz, Identity-H, ToUnicode glyph -> "fi")
/// and Type3 (matplotlib) fonts, form XObjects, empty pages, owner-only
/// encryption: all correct. Kept as guards.
#[cfg(feature = "pdf")]
#[test]
fn pdf_guards_that_pass() {
    let t = |n: &str| deformat::pdf::extract_bytes(&fixture(n)).unwrap().text;
    assert_eq!(t("shaped_lig.pdf"), "find the flow and offer office");
    assert_eq!(t("type3.pdf"), "Typethree glyph text");
    assert!(t("identity_h.pdf").contains("Identity encoded café αβγ"));
    assert!(t("form.pdf").contains("Inside the form xobject"));
    assert_eq!(t("emptymid.pdf"), "Page one text\n\nPage three text");
    assert_eq!(t("enc_owner_only.pdf"), "Hello world");
    assert_eq!(t("nospace.pdf"), "Separately placed words");
    for n in ["enc_aes256.pdf", "enc_aes128.pdf", "enc_rc4.pdf"] {
        assert!(
            deformat::pdf::extract_bytes(&fixture(n)).is_err(),
            "{n} must error"
        );
    }
}

/// A soft hyphen (U+00AD) at a line end marks a hyphenation point; the hard
/// hyphen "extra-\nordinary" in the same file is joined, the soft one is kept
/// as an invisible character plus a newline, so the word is split in two.
/// pdftotext: "information"; PyMuPDF: "infor-\nmation".
#[cfg(feature = "pdf")]
#[test]
fn pdf_soft_hyphen_at_line_end_does_not_split_word_invisibly() {
    let got = deformat::pdf::extract_bytes(&fixture("hyphen.pdf"))
        .unwrap()
        .text;
    assert!(got.contains("extraordinary"), "control: {got:?}");
    assert!(
        !got.contains('\u{ad}'),
        "invisible soft hyphen left in output: {got:?}"
    );
}

/// Same document, two deformat APIs: `pdf::extract_bytes` expands ligature
/// code points (U+FB01 -> "fi"), `extract_bytes_to_segments_with_coords`
/// does not, so the per-line segments are not substrings of the page text.
#[cfg(feature = "pdf_oxide")]
#[test]
fn pdf_line_segments_use_same_text_normalization_as_extract() {
    let b = fixture("ttf_lig.pdf");
    let text = deformat::pdf_oxide::extract_bytes(&b).unwrap().text;
    let segs = deformat::pdf_oxide::extract_bytes_to_segments_with_coords(&b).unwrap();
    for s in segs {
        assert!(
            text.contains(&s.data().text),
            "segment {:?} not in text {:?}",
            s.data().text,
            text
        );
    }
}

// ---------------------------------------------------------------- coordinates

/// Coordinates doc (segment.rs:131): points are [top-left, top-right,
/// bottom-right, bottom-left]. In PointSpace (PDF user space, y up) the first
/// point must therefore have the larger y.
#[cfg(feature = "pdf_oxide")]
#[test]
#[ignore = "open: PDF corners start bottom-left"]
fn pdf_coordinates_first_point_is_top_left() {
    let segs =
        deformat::pdf_oxide::extract_bytes_to_segments_with_coords(&fixture("simple.pdf")).unwrap();
    let c = segs[0].data().metadata.coordinates.clone().unwrap();
    assert_eq!(c.system, "PointSpace");
    let (tl, bl) = (c.points[0], c.points[3]);
    // y-up: top-left.y > bottom-left.y. (y-down would need system PixelSpace
    // and the y values flipped against layout_height.)
    assert!(
        tl.1 > bl.1,
        "points {:?}: first point is the bottom-left corner",
        c.points
    );
}

/// MediaBox [50 600 400 800]: layout_width/height are 350 x 200, but the line
/// bbox is reported in absolute user space (72, 700), outside the layout.
#[cfg(feature = "pdf_oxide")]
#[test]
#[ignore = "open: PDF points ignore a MediaBox offset"]
fn pdf_coordinates_lie_inside_layout_for_offset_mediabox() {
    let segs =
        deformat::pdf_oxide::extract_bytes_to_segments_with_coords(&fixture("mediabox_offset.pdf"))
            .unwrap();
    let c = segs[0].data().metadata.coordinates.clone().unwrap();
    for &(x, y) in &c.points {
        assert!(
            (0.0..=c.layout_width).contains(&x) && (0.0..=c.layout_height).contains(&y),
            "point ({x},{y}) outside layout {}x{}",
            c.layout_width,
            c.layout_height
        );
    }
}

/// /Rotate 90 on a 612x792 page: the page is displayed 792 wide, 612 high.
#[cfg(feature = "pdf_oxide")]
#[test]
#[ignore = "open: PDF points ignore /Rotate"]
fn pdf_coordinates_account_for_page_rotation() {
    let segs = deformat::pdf_oxide::extract_bytes_to_segments_with_coords(&fixture("rotated.pdf"))
        .unwrap();
    let c = segs[0].data().metadata.coordinates.clone().unwrap();
    assert_eq!(
        (c.layout_width, c.layout_height),
        (792.0, 612.0),
        "rotation ignored"
    );
}

// ---------------------------------------------------------------- page_type

/// og:type with content= before property= (documented: "Match either order"),
/// followed by another meta: the forward window reads the *next* tag's content.
#[test]
#[ignore = "open: page_type reads the wrong meta when content= precedes property="]
fn page_type_og_type_content_before_property() {
    use deformat::page_type::{detect_page_type, PageType};
    let html = r#"<html><head><meta content="product" property="og:type"><meta content="Blue Widget" property="og:title"></head><body><p>x</p></body></html>"#;
    assert_eq!(detect_page_type(html), PageType::Product);
}

/// The canonical href is read from the first href= in a 200-byte window that
/// starts before rel="canonical", i.e. from the preceding <link>.
#[test]
#[ignore = "open: page_type canonical href taken from the wrong link"]
fn page_type_canonical_href_comes_from_canonical_link() {
    use deformat::page_type::{detect_page_type, PageType};
    let html = r#"<html><head><link rel="alternate" hreflang="de" href="https://example.com/de/forum/thread-9"><link rel="canonical" href="https://example.com/blog/2026/05/post"></head><body><p>x</p></body></html>"#;
    assert_eq!(detect_page_type(html), PageType::Article);
}
